package project.kosh.core.network

import okhttp3.OkHttpClient
import java.security.MessageDigest
import java.security.cert.CertificateException
import java.security.cert.X509Certificate
import javax.inject.Inject
import javax.inject.Singleton
import javax.net.ssl.SSLContext
import javax.net.ssl.SSLSocketFactory
import javax.net.ssl.TrustManager
import javax.net.ssl.X509TrustManager

/**
 * Custom [X509TrustManager] enforcing Trust-On-First-Use (TOFU) SHA-256 certificate fingerprint pinning.
 *
 * Self-signed TLS certificates generated by the Kosh server on local networks cannot be verified
 * against standard Android CA trust anchors. This trust manager intercepts the server's X.509
 * leaf certificate during the TLS handshake, computes its SHA-256 digest over DER-encoded bytes,
 * and matches it against the expected fingerprint pinned out-of-band during device pairing.
 *
 * All comparisons are performed in constant time using [MessageDigest.isEqual] to prevent
 * timing side-channel attacks.
 *
 * @param fingerprintProvider Lambda supplying the expected 32-byte SHA-256 fingerprint, or null if unpinned.
 */
@Singleton
class KoshPinnedTrustManager(
    private val fingerprintProvider: () -> ByteArray?
) : X509TrustManager {

    @Inject
    constructor(serverConfigStore: ServerConfigurationStore) : this({
        serverConfigStore.getPinnedFingerprint()
    })

    constructor(expectedFingerprintBytes: ByteArray) : this({
        expectedFingerprintBytes
    })

    override fun checkClientTrusted(chain: Array<out X509Certificate>?, authType: String?) {
        // Client certificate authentication is not utilized in Kosh TOFU transport
    }

    /**
     * Validates that the server presents a valid certificate chain and that the leaf certificate
     * exactly matches the expected pinned SHA-256 fingerprint.
     *
     * @param chain The peer certificate chain presented during the TLS handshake.
     * @param authType The key exchange algorithm used (e.g. "ECDHE_RSA", "UNKNOWN").
     * @throws CertificateException If the chain is empty, no fingerprint is pinned, or the fingerprint does not match.
     */
    override fun checkServerTrusted(chain: Array<out X509Certificate>?, authType: String?) {
        if (chain.isNullOrEmpty()) {
            throw CertificateException("Server presented empty certificate chain")
        }

        val expected = fingerprintProvider()
            ?: throw CertificateException("Certificate pinning failed: No certificate fingerprint pinned")

        if (expected.size != 32) {
            throw CertificateException(
                "Certificate pinning failed: Invalid pinned fingerprint length (expected 32 bytes, got ${expected.size})"
            )
        }

        val leafCert = chain[0]
        val derBytes = leafCert.encoded

        val md = MessageDigest.getInstance("SHA-256")
        val actual = md.digest(derBytes)

        if (!MessageDigest.isEqual(expected, actual)) {
            val expectedHex = expected.joinToString("") { "%02x".format(it) }
            val actualHex = actual.joinToString("") { "%02x".format(it) }
            throw CertificateException(
                "Certificate pinning failed! Potential MitM attack or untrusted server. Expected: $expectedHex, Actual: $actualHex"
            )
        }
    }

    override fun getAcceptedIssuers(): Array<X509Certificate> = emptyArray()
}

/**
 * Factory utilities for constructing OkHttp instances configured with [KoshPinnedTrustManager].
 */
object PinnedHttpClientFactory {

    /**
     * Creates an initialized [SSLSocketFactory] and companion [X509TrustManager] bound to the given trust manager.
     */
    fun createSslSocketFactory(trustManager: X509TrustManager): Pair<SSLSocketFactory, X509TrustManager> {
        val sslContext = SSLContext.getInstance("TLS")
        sslContext.init(null, arrayOf<TrustManager>(trustManager), null)
        return sslContext.socketFactory to trustManager
    }

    /**
     * Instantiates an [OkHttpClient] configured with leaf certificate pinning and permissive hostname verification.
     * Permissive hostname verification is safe because authenticity is established out-of-band by certificate hash pinning.
     */
    fun create(
        pinnedFingerprint: ByteArray,
        builderModifier: (OkHttpClient.Builder.() -> Unit)? = null
    ): OkHttpClient {
        val trustManager = KoshPinnedTrustManager(pinnedFingerprint)
        val (socketFactory, tm) = createSslSocketFactory(trustManager)

        return OkHttpClient.Builder()
            .dns(KoshDns)
            .sslSocketFactory(socketFactory, tm)
            .hostnameVerifier { _, _ -> true }
            .apply { builderModifier?.invoke(this) }
            .build()
    }
}
